VALUES
(1, '2026.10.20', '00:52', '站点', '["上线","GitHub Pages"]', 'bg2hhw.top 正式上线。域名、HTTPS 和 GitHub Pages 终于连成一条线。今晚最后一件事，是把这个动态页也放上去。', NULL, NULL, NULL, '打开主页', '../', 1, '2026-10-20 00:00:00', '2026-10-20 00:00:00'),
(2, '2026.10.19', '23:10', '设计', '["QSL","印刷"]', '把 QSL 2026 的三款卡重新看了一遍。航海日志那版最像我想留下的东西：一点风、一点噪声，还有一张能被寄出去的纸。', NULL, NULL, NULL, '去主页看 QSL', '../#work', 1, '2026-10-19 00:00:00', '2026-10-19 00:00:00'),
(3, '2026.10.17', '全天', '无线电', '["猎狐","BY2HIT","赛事"]', '17 号当天，我们在第二届中俄大学生科技人文交流活动现场举办了无线电猎狐挑战赛，持续了一整天。广场上的终点箱，是那天最具体的一个坐标。', '../assets/moments/2026-10-17-radio-foxhunt.webp', '第二届中俄大学生科技人文交流活动现场的无线电猎狐挑战赛终点箱', '2026.10.17 / RADIO FOXHUNT', NULL, NULL, 1, '2026-10-17 00:00:00', '2026-10-17 00:00:00'),
(4, '2026.10.17', '下午 / 赛后', '无线电', '["BY2HIT","BY4WNG","交流"]', '10 月 17 日下午，无线电猎狐挑战赛结束后，和东南大学业余无线电协会的同学合影。BY2HIT 和 BY4WNG 的旗子出现在同一张照片里。', '../assets/moments/2026-10-17-southeast-university.webp', 'BG2HHW 与东南大学业余无线电协会 BY4WNG 学生在交流活动上的合影', '2026.10.17 / BY2HIT × BY4WNG', NULL, NULL, 1, '2026-10-17 00:00:00', '2026-10-17 00:00:00'),
(5, '2026.10.16', '22:30', '无线电', '["短波","CW"]', '晚上翻了一会儿短波。噪声很大，但还是愿意多听几分钟。有些信号不是为了听清，只是为了知道远处有人在。', NULL, NULL, NULL, '回到首页', '../', 1, '2026-10-16 00:00:00', '2026-10-16 00:00:00'),
(6, '2026.10.15', '19:20', '站点', '["导航","整理"]', '把主页的导航重新排了一遍，删掉了一些看起来热闹、其实没人会点的东西。现在每个入口都知道自己要去哪里。', NULL, NULL, NULL, '看看新主页', '../', 1, '2026-10-15 00:00:00', '2026-10-15 00:00:00'),
(7, '2026.10.14', '23:05', '日常', '["桌面","整理"]', '把桌面收拾出一块能放下电键的地方。房间没有变大，但好像多了一点可以安静下来的空间。', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 00:00:00', '2026-10-14 00:00:00'),
(8, '2026.10.13', '18:45', '设计', '["纸张","档案"]', '在纸上试了几种新的标题排版。屏幕上的完美和纸上的呼吸感，还是两件不同的事。', NULL, NULL, NULL, 'QSL 2026', '../#work', 1, '2026-10-13 00:00:00', '2026-10-13 00:00:00'),
(9, '2026.10.08', '当天', '无线电', '["航天70周年","SSDV","阿斯图友谊号"]', '10 月 8 日接收到了阿斯图友谊号发的 SSDV。', '../assets/moments/2026-10-08-ssdv-reception.webp', '从阿斯图友谊号接收到的 SSDV 画面，包含中国国旗和彩色测试条', '2026.10.08 / SSDV RECEPTION', '航天 70 周年项目', '../#work', 1, '2026-10-08 00:00:00', '2026-10-08 00:00:00');
